export interface ProductoRepositorio { buscar(id: string): Promise<Producto | null>; }
export interface PedidoRepositorio { guardar(p: Pedido): Promise<void>; }

export class RegistrarCompra {
  constructor(private productos: ProductoRepositorio,
              private pedidos: PedidoRepositorio) {}

  async ejecutar(entrada: { usuarioId: string; productoId: string; cantidad: number }) {
    const producto = await this.productos.buscar(entrada.productoId);
    if (!producto) throw new Error('Producto inexistente');
    const pedido = Pedido.crear(entrada.usuarioId, producto, entrada.cantidad);
    await this.pedidos.guardar(pedido);
    return pedido.resumen();
  }
}

// adaptadores/http
app.post('/api/compras', async (req, res) => {
  res.status(201).json(await registrarCompra.ejecutar(req.body));
});

// adaptadores/cli
const [productoId, cantidad] = process.argv.slice(2);
console.log(await registrarCompra.ejecutar({ usuarioId: 'admin', productoId, cantidad: +cantidad }));

